<?php use Hls\Http\View as V; ?><?php if($error): ?><div class="alert alert-error"><?= V::escape($error) ?></div><?php endif ?><?php if($access->can('finance.expense.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Tanggal<input type="date" name="expense_date" value="<?= date('Y-m-d') ?>" required></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Kategori<select name="category_id" required><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>"><?= V::escape($c['code'].' - '.$c['name']) ?></option><?php endforeach ?></select></label><label>Rekening<select name="account_id" required><?php foreach($accounts as $a): if($access->branch((int)$a['branch_id'])): ?><option value="<?= (int)$a['id'] ?>"><?= V::escape($a['code'].' - '.$a['name']) ?></option><?php endif; endforeach ?></select></label><label>Nominal<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Referensi<input name="reference" required maxlength="80"></label><label>Keterangan<input name="description" maxlength="255"></label><button class="button button-primary">Catat Pengeluaran</button></form></section><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Referensi</th><th>Kategori</th><th>Rekening</th><th>Nominal</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['expense_date']) ?></td><td><?= V::escape($r['description']) ?></td><td><?= V::escape($r['category_code']) ?></td><td><?= V::escape($r['account_code']) ?></td><td><?= \Hls\Http\View::money($r['amount']) ?></td><td><?= V::escape($r['status']) ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada transaksi pengeluaran.</p><?php endif ?></div></section>
